import{_ as l,a0 as n,w as p,s as d,ao as r,I as o,x as t,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"将 Zeek 与 ELK 栈集成 | LCTT x X-CMD","titleTemplate":false,"description":"将 Zeek 与 ELK 栈集成 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将 Zeek 与 ELK 栈集成 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将 Zeek 与 ELK 栈集成 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220607 Integrating Zeek with ELK Stack","title":"将 Zeek 与 ELK 栈集成","tag":"202206","desc":""},"relativePath":"202206/20220607 Integrating Zeek with ELK Stack.md","filePath":"[post].md"}'),c={name:"202206/20220607 Integrating Zeek with ELK Stack.md"};function g(k,e,h,u,b,f){const s=n("Link");return p(),d("div",null,[e[15]||(e[15]=r(`<h1 id="将-zeek-与-elk-栈集成" tabindex="-1">将 Zeek 与 ELK 栈集成 <a class="header-anchor" href="#将-zeek-与-elk-栈集成" aria-label="Permalink to “将 Zeek 与 ELK 栈集成”">​</a></h1><blockquote><p>Zeek 是一个开源的网络安全监控工具。本文讨论了如何将 Zeek 与 ELK 集成。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202206/28/164550v4nuk3g7ux77y77v.jpg" alt=""></p><p>在本杂志 2022 年 3 月版发表的题为“用 Zeek 轻松实现网络安全监控”的文章中，我们研究了 Zeek 的功能，并学习了如何开始使用它。现在我们将把我们的学习经验再进一步，看看如何将其与 ELK（即 Elasticsearch、Kibana、Beats 和 Logstash）整合。</p><p>为此，我们将使用一个叫做 Filebeat 的工具，它可以监控、收集并转发日志到 Elasticsearch。我们将把 Filebeat 和 Zeek 配置在一起，这样后者收集的数据将被转发并集中到我们的 Kibana 仪表盘上。</p><h3 id="安装-filebeat" tabindex="-1">安装 Filebeat <a class="header-anchor" href="#安装-filebeat" aria-label="Permalink to “安装 Filebeat”">​</a></h3><p>让我们首先将 Filebeat 与 Zeek 安装在一起。使用 <code>apt</code> 来安装 Filebeat，使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install filebeat</span></span></code></pre></div><p>接下来，我们需要配置 <code>.yml</code> 文件，它位于 <code>/etc/filebeat/</code> 文件夹中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/filebeat/filebeat.yml</span></span></code></pre></div><p>我们只需要在这里配置两件事。在 Filebeat 输入部分，将类型改为 <code>log</code>，并取消对 <code>enabled:false</code> 的注释，将其改为 <code>true</code>。我们还需要指定存储日志的路径，也就是说，我们需要指定 <code>/opt/zeek/logs/current/*.log</code>。</p><p>完成这些后，设置的第一部分应该类似于图 1 所示的内容。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Filebeat-config-a.jpg" alt="Figure 1: Filebeat config (a)"></p><p>第二件要修改的事情是在输出下的 Elasticsearch 输出部分，取消对 <code>output.elasticsearch</code> 和 <code>hosts</code> 的注释。确保主机的 URL 和端口号与你安装 ELK 时配置的相似。我们把它保持为 <code>localhost</code>，端口号为 <code>9200</code>。</p><p>在同一部分中，取消底部的用户名和密码的注释，输入安装后配置 ELK 时生成的 Elasticsearch 用户的用户名和密码。完成这些后，参考图 2，检查设置。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-Filebeat-config-b.jpg" alt="Figure 2: Filebeat config (b)"></p><p>现在我们已经完成了安装和配置，我们需要配置 Zeek，使其以 JSON 格式存储日志。为此，确保你的 Zeek 实例已经停止。如果没有，执行下面的命令来停止它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /opt/zeek/bin</span></span>
<span class="line"><span>./zeekctl stop</span></span></code></pre></div><p>现在我们需要在 <code>local.zeek</code> 中添加一小行，它存在于 <code>opt/zeek/share/zeek/site/</code> 目录中。</p><p>以 root 身份打开该文件，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@load policy/tuning/json-logs.zeek</span></span></code></pre></div><p>参考图 3，确保设置正确。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-3-local.zeek-file-1.jpg" alt="Figure 3: local.zeek file"></p><p>由于我们改变了 Zeek 的一些配置，我们需要重新部署它，这可以通过执行以下命令来完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /opt/zeek/bin</span></span>
<span class="line"><span>./zeekctl deploy</span></span></code></pre></div><p>现在我们需要在 Filebeat 中启用 Zeek 模块，以便它转发 Zeek 的日志。执行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo filebeat modules enable zeek</span></span></code></pre></div><p>我们几乎要好了。在最后一步，配置 <code>zeek.yml</code> 文件要记录什么类型的数据。这可以通过修改 <code>/etc/filebeat/modules.d/zeek.yml</code> 文件完成。</p><p>在这个 .yml 文件中，我们必须提到这些指定的日志存放在哪个目录下。我们知道，这些日志存储在当前文件夹中，其中有几个文件，如 <code>dns.log</code>、<code>conn.log</code>、<code>dhcp.log</code> 等等。我们需要在每个部分提到每个路径。如果而且只有在你不需要该文件/程序的日志时，你可以通过把启用值改为 <code>false</code> 来舍弃不需要的文件。</p><p>例如，对于 <code>dns</code>，确保启用值为 <code>true</code>，并且路径被配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var.paths: [ “/opt/zeek/logs/current/dns.log”, “/opt/zeek/logs/*.dns.json” ]</span></span></code></pre></div><p>对其余的文件重复这样做。我们对一些我们需要的文件做了这个处理。我们添加了所有主要需要的文件。你也可以这样做。请参考图 4。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-4-zeek.yml-configuration.jpg" alt="Figure 4: zeek.yml configuration"></p><p>现在是启动 Filebeat 的时候了。执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo filebeat setup</span></span>
<span class="line"><span>sudo service filebeat start</span></span></code></pre></div><p>现在一切都完成了，让我们移动到 Kibana 仪表板，检查我们是否通过 Filebeat 接收到来自 Zeek 的数据。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-5-Dashboard-of-Kibana-Destination-Geo.jpg" alt="Figure 5: Dashboard of Kibana (Destination Geo)"></p><p>进入仪表板。你可以看到它所捕获的数据的清晰统计分析（图 5 和图 6）。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-6-Dashboard-of-Kibana-Network-1.jpg" alt="Figure 6: Dashboard of Kibana (Network)"></p><p>现在让我们进入发现选项卡，通过使用查询进行过滤来检查结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>event.module: &quot;zeek&quot;</span></span></code></pre></div><p>这个查询将过滤它在一定时间内收到的所有数据，只向我们显示名为 Zeek 的模块的数据（图 7）。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-7-Filtered-data-by-event.jpg" alt="Figure 7: Filtered data by event.module query"></p><h3 id="鸣谢" tabindex="-1">鸣谢 <a class="header-anchor" href="#鸣谢" aria-label="Permalink to “鸣谢”">​</a></h3><p><em>作者感谢 VIT-AP 计算机科学与工程学院的 Sibi Chakkaravarthy Sethuraman、Sudhakar Ilango、Nandha Kumar R.和Anupama Namburu 的不断指导和支持。特别感谢人工智能和机器人技术卓越中心（AIR）。</em></p><hr>`,46)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),a(s,{href:"https://www.opensourceforu.com/2022/06/integrating-zeek-with-elk-stack/"},{default:i(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/06/integrating-zeek-with-elk-stack/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),a(s,{href:"https://www.opensourceforu.com/author/tridev-reddy/"},{default:i(()=>[...e[2]||(e[2]=[t("Tridev Reddy",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),a(s,{href:"https://github.com/lkxed"},{default:i(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),a(s,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const C=l(c,[["render",g]]);export{y as __pageData,C as default};
